CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY, token_hash text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence (id text PRIMARY KEY, title text NOT NULL, revision integer NOT NULL, section text NOT NULL, current boolean NOT NULL, text text NOT NULL, keywords text NOT NULL, search tsvector GENERATED ALWAYS AS (to_tsvector('english', keywords)) STORED);
CREATE INDEX IF NOT EXISTS evidence_search_idx ON evidence USING gin(search);
CREATE TABLE IF NOT EXISTS runs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, case_id text NOT NULL, status text NOT NULL CHECK (status IN ('queued','running','ready','failed','cancelled')), corpus_revision text NOT NULL, brief jsonb, draft text NOT NULL DEFAULT '', cursor integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), task_id uuid);
CREATE TABLE IF NOT EXISTS jobs (run_id uuid PRIMARY KEY REFERENCES runs ON DELETE CASCADE, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','leased','done','failed')), fence integer NOT NULL DEFAULT 0, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, available_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events (run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, seq integer NOT NULL, type text NOT NULL, data text NOT NULL, PRIMARY KEY(run_id,seq));
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, run_id uuid UNIQUE NOT NULL REFERENCES runs, title text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals (workspace_id uuid NOT NULL REFERENCES workspaces, key text NOT NULL, digest text NOT NULL, task_id uuid NOT NULL REFERENCES tasks, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,key));
